  const base = require('../test/fixtures/config.json');
  for (const value of [0, 60, 3600]) assert.doesNotThrow(() => createPolicy({...base, verification_queue_grace_seconds: value}));
  for (const value of [-1, 3601, 1.5, '900', null]) {
