  if (/\s/.test(value)) return 'contains whitespace or a line break';
  if (/[^\x21-\x7e]/.test(value)) return 'contains a non-printable or non-ASCII character';
  if (/^["']|["']$/.test(value)) return 'is wrapped in quotation marks';
